"""The `references` command: every occurrence of the symbol under the cursor.

Occurrences are matched by symbol identity, not spelling: a symbol is the
scope a name is bound in plus the name (the owning class for attributes), with
imports followed to what they import, a module, or a runtime object.
"""
import ast
import os
import re
from dataclasses import asdict, dataclass

from .definitions import DefinitionFactory
from .errors import SithError
from .inference import BuiltinBinding, Inferrer
from .modules import Importer
from .navigation import Navigator
from .project import project_files
from .scopes import Binding
from .source import load_document, read_text
from .values import LocalClass, LocalFunction, LocalInstance, LocalModule

FILE = "file"
PROJECT = "project"
_DEFINING_KINDS = ("def", "param", "bound")


@dataclass
class Reference:
    module_path: str
    line: int
    column: int
    is_definition: bool

    def to_dict(self):
        return asdict(self)


def find_references(path, line, col, scope=FILE, project=None):
    """References to the name at the cursor, in `path` or (`scope` "project") the whole project."""
    document = load_document(path)
    document.check_position(line, col)
    root = os.path.abspath(project or document.directory)
    importer = Importer(root)
    context = importer.context_for_file(document.path)
    if context is None:
        raise SithError(f"cannot analyze {path}")
    inferrer = Inferrer(importer)
    factory = DefinitionFactory(inferrer, root)
    navigator = Navigator(context, inferrer, factory, line, col)
    occurrence = navigator.occurrence()
    if occurrence is None:
        raise SithError(f"no name at line {line}, column {col}")
    finder = _Finder(inferrer)
    target = finder.symbols(navigator, line, occurrence)
    name = occurrence.name
    navigators = [navigator]
    if scope == PROJECT:
        word = _word(name)
        for file_path in project_files(root):
            if os.path.abspath(file_path) == context.path:
                continue
            try:
                if not word.search(read_text(file_path)):
                    continue
            except SithError:
                continue
            other = importer.context_for_file(file_path)
            if other is not None:
                navigators.append(Navigator(other, inferrer, factory))
    found = {}
    for current in navigators:
        module_path = factory.relative_path(current.context.path)
        for number, occurrence_found in _named_occurrences(current, name):
            if target:
                matches = bool(finder.symbols(current, number, occurrence_found) & target)
            else:
                # Unresolved name: match the other unresolved uses in the same file.
                matches = current is navigator and not finder.symbols(current, number,
                                                                       occurrence_found)
            if matches:
                key = (module_path, number, occurrence_found.start)
                defining = _is_definition(occurrence_found)
                found[key] = found.get(key, False) or defining
    if occurrence.kind == "text":  # an identifier missing from the (repaired) syntax tree
        found.setdefault((factory.relative_path(context.path), line, occurrence.start), False)
    return [Reference(path_, number, column, defining)
            for (path_, number, column), defining in sorted(found.items())]


def _word(name):
    return re.compile(r"(?<!\w)" + re.escape(name) + r"(?!\w)")


def _named_occurrences(navigator, name):
    """(line, occurrence) for every occurrence of `name` in the navigator's module."""
    word = _word(name)
    for number, text in enumerate(navigator.context.lines, start=1):
        if not word.search(text):
            continue
        navigator.at(number, 0)
        starts = set()
        for occurrence in navigator.occurrences():
            if occurrence.name == name and occurrence.start not in starts:
                starts.add(occurrence.start)
                yield number, occurrence


def _is_definition(occurrence):
    if occurrence.kind in _DEFINING_KINDS:
        return True
    if occurrence.kind in ("name", "attr"):
        return isinstance(getattr(occurrence.node, "ctx", None), ast.Store)
    return False


class _Finder:
    def __init__(self, inferrer):
        self.inferrer = inferrer

    def symbols(self, navigator, line, occurrence):
        """The set of symbols the occurrence at `line` refers to."""
        navigator.at(line, occurrence.start)
        try:
            sources = navigator.goto(occurrence)
        except Exception:
            return set()
        return self._symbols(navigator, sources)

    def _symbols(self, navigator, sources):
        result = set()
        for source in sources:
            if source is None:
                continue
            if isinstance(source, BuiltinBinding):
                result.add(("builtin", source.name))
            elif isinstance(source, Binding):
                if source.kind in ("import", "importfrom"):
                    result |= self._import_symbols(navigator, source)
                else:
                    owner = source.extra.get("owner")
                    result.add(("scope", id(owner or source.scope), source.name))
            else:
                result.add(_value_symbol(source))
        return result

    def _import_symbols(self, navigator, binding):
        followed = navigator._follow(binding, set())
        if followed:
            return self._symbols(navigator, followed)
        values = [v for v in self.inferrer.binding_values(binding) if v is not None]
        if values:
            return {_value_symbol(v) for v in values}
        return {("scope", id(binding.scope), binding.name)}


def _value_symbol(value):
    if isinstance(value, LocalModule):
        return ("module", value.context.location)
    if isinstance(value, (LocalClass, LocalFunction)):
        node = value.scope.node
        if isinstance(node, ast.Lambda):
            return ("node", id(node))
        return ("scope", id(value.scope.parent), node.name)
    if isinstance(value, LocalInstance):
        return ("instance", id(value.cls.scope))
    return ("runtime",) + value.key
"""Enumerating the Python source files of a project."""
import os

_SKIPPED_DIRECTORIES = {"__pycache__", "node_modules", "site-packages"}


def project_files(root):
    """Absolute paths of the `.py` files under `root`, in a stable order.

    Hidden directories, caches and virtual environments are skipped.
    """
    root = os.path.abspath(root)
    for directory, subdirectories, files in os.walk(root):
        subdirectories[:] = sorted(
            name for name in subdirectories
            if not name.startswith(".") and name not in _SKIPPED_DIRECTORIES
            and not os.path.isfile(os.path.join(directory, name, "pyvenv.cfg")))
        for name in sorted(files):
            if name.endswith(".py"):
                yield os.path.join(directory, name)
"""Loading source documents and validating cursor positions."""
import os
from dataclasses import dataclass, field

from .errors import SithError


@dataclass
class Document:
    """A source file split into lines, with cursor-related helpers."""

    path: str
    text: str
    lines: list = field(default_factory=list)

    @property
    def directory(self):
        return os.path.dirname(os.path.abspath(self.path))

    def check_position(self, line, col):
        """Validate a 1-based line and 0-based column."""
        if line < 1 or line > len(self.lines):
            raise SithError(f"line {line} is out of range (file has {len(self.lines)} lines)")
        length = len(self.lines[line - 1])
        if col < 0 or col > length:
            raise SithError(f"column {col} is out of range (line {line} has {length} characters)")

    def text_before(self, line, col):
        """All source text preceding the cursor."""
        return "\n".join(self.lines[: line - 1] + [self.lines[line - 1][:col]])


def normalize_newlines(text):
    return text.replace("\r\n", "\n").replace("\r", "\n")


def read_text(path):
    """Read a file as UTF-8 text, raising SithError on any problem."""
    if not os.path.exists(path):
        raise SithError(f"file not found: {path}")
    if not os.path.isfile(path):
        raise SithError(f"not a regular file: {path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        raise SithError(f"cannot read {path}: {exc}") from exc
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SithError(f"file is not valid UTF-8: {path}") from exc
    if text.startswith("\ufeff"):
        text = text[1:]
    return normalize_newlines(text)


def load_document(path):
    text = read_text(path)
    return Document(path=path, text=text, lines=text.split("\n"))
"""Lazily-described completion candidates.

An entry stands for whatever a name refers to; its value and description are
only computed when the name survives prefix filtering.
"""
from .describe import (
    describe_class,
    describe_function,
    describe_module,
    describe_param,
    describe_value,
)

_UNSET = object()


class BindingEntry:
    """A name bound by a statement in parsed source."""

    def __init__(self, binding, inferrer):
        self.binding = binding
        self.inferrer = inferrer

    def value(self):
        return self.inferrer.infer_binding(self.binding)

    def describe(self, name):
        kind = self.binding.kind
        if kind == "param":
            return describe_param(name)
        if kind == "def":
            return describe_function(name)
        if kind == "class":
            return describe_class(name)
        if kind == "import":
            return describe_module(name)
        return describe_value(name, self.value())


class ValueEntry:
    """A name whose value is produced on demand by a factory."""

    def __init__(self, factory):
        self._factory = factory
        self._value = _UNSET

    def value(self):
        if self._value is _UNSET:
            try:
                self._value = self._factory()
            except Exception:
                self._value = None
        return self._value

    def describe(self, name):
        return describe_value(name, self.value())
"""Exception types used across sith."""


class SithError(Exception):
    """A user-facing error: reported on STDERR and turned into exit code 1."""
"""Finding the innermost scope that contains the cursor."""
import ast

from .scopes import COMPREHENSION, LAMBDA

_DEFINITIONS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)


def cursor_indent(line_text, col):
    """Indentation that governs the cursor's block membership."""
    before = line_text[:col]
    if not before.strip():
        return len(before)
    return len(line_text) - len(line_text.lstrip())


def find_scope(context, line, col, line_text):
    """The innermost Scope of `context` enclosing the cursor at (line, col)."""
    byte_col = len(line_text[:col].encode("utf-8"))
    indent = cursor_indent(line_text, col)
    scope = context.root
    for node in _definition_chain(context.tree.body, line, byte_col, indent):
        scope = context.scope_of(node) or scope
    return _innermost_expression_scope(scope, line, byte_col)


def _definition_chain(statements, line, byte_col, indent):
    """def/class nodes whose bodies contain the cursor, outermost first."""
    chain = []
    while True:
        candidate = None
        for statement in statements:
            if statement.lineno <= line:
                candidate = statement
            else:
                break
        if candidate is None:
            return chain
        inside = line <= candidate.end_lineno or indent > candidate.col_offset
        if not inside:
            return chain
        if isinstance(candidate, _DEFINITIONS):
            if not _in_body(candidate, line, byte_col):
                return chain
            chain.append(candidate)
            statements = candidate.body
        else:
            statements = _child_statements(candidate)
            if not statements:
                return chain


def _in_body(node, line, byte_col):
    first = node.body[0]
    if line > _header_end(node):
        return True
    return line == first.lineno and byte_col >= first.col_offset


def _header_end(node):
    parts = []
    if isinstance(node, ast.ClassDef):
        parts = node.bases + [k.value for k in node.keywords]
    else:
        args = node.args
        parts = args.posonlyargs + args.args + args.kwonlyargs + args.defaults
        parts += [d for d in args.kw_defaults if d is not None]
        parts += [a for a in (args.vararg, args.kwarg, node.returns) if a is not None]
    return max([node.lineno] + [getattr(p, "end_lineno", None) or node.lineno for p in parts])


def _child_statements(node):
    children = []
    for field in ("body", "orelse", "finalbody"):
        children += [s for s in getattr(node, field, []) if isinstance(s, ast.stmt)]
    for handler in getattr(node, "handlers", []):
        children += handler.body
    for case in getattr(node, "cases", []):
        children += case.body
    return sorted(children, key=lambda s: (s.lineno, s.col_offset))


def _contains(node, line, byte_col):
    start = (node.lineno, node.col_offset)
    end = (node.end_lineno, node.end_col_offset)
    return start <= (line, byte_col) <= end


def _innermost_expression_scope(scope, line, byte_col):
    """Descend into lambda/comprehension scopes that contain the cursor."""
    while True:
        for child in scope.children:
            if child.kind in (LAMBDA, COMPREHENSION) and _contains(child.node, line, byte_col):
                scope = child
                break
        else:
            return scope

